package com.fitbite.controller; import com.fitbite.dto.*; import com.fitbite.dto.RecommendationDtos.*; import com.fitbite.recommendation.RecommendationService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/ingredients") public class IngredientRecommendationController{private final RecommendationService service;public IngredientRecommendationController(RecommendationService service){this.service=service;}@PostMapping("/recommend") public ApiResponse<?> recommend(@Valid @RequestBody IngredientRecommendationRequest r){return ApiResponse.ok("Ingredient recommendations generated",service.byIngredients(r.ingredients()));}}
